import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec4 } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-title';

  const pos = config.position || [0, 3, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  // ---- Background sprite (atlas region) ----
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = { w: 512, h: 320 }; // assume single-region atlas texture matches source dims

  const aspect = atlasRect.w / atlasRect.h;
  const height = 0.62; // headline-scale em height reference
  const width = height * aspect * 1.5;

  const geometry = new THREE.PlaneGeometry(width, height);

  const rawTexture = ctx.textureLoader.load(config.imageUrl || '/prism-mock/home/nodes/floating-accent.png');
  rawTexture.colorSpace = THREE.SRGBColorSpace;
  rawTexture.wrapS = THREE.ClampToEdgeWrapping;
  rawTexture.wrapT = THREE.ClampToEdgeWrapping;

  const uOffset = atlasRect.x / atlasSize.w;
  const vOffset = 1 - (atlasRect.y + atlasRect.h) / atlasSize.h;
  const uScale = atlasRect.w / atlasSize.w;
  const vScale = atlasRect.h / atlasSize.h;

  const atlasUv = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));
  const mapNode = texture(rawTexture, atlasUv);

  const material = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  material.colorNode = mapNode;
  material.opacityNode = mapNode.a;

  const spriteMesh = new THREE.Mesh(geometry, material);
  spriteMesh.name = 'hub-journal-title-bg';
  group.add(spriteMesh);

  // ---- Billboard behavior (manual, since this is a plane not THREE.Sprite) ----
  const billboardUpdate = () => {
    if (ctx.camera) {
      spriteMesh.quaternion.copy(ctx.camera.quaternion);
    }
  };
  if (ctx.registerFrameCallback) {
    ctx.registerFrameCallback(billboardUpdate);
  }

  // ---- Headline text: "Journal" ----
  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: 'Journal',
      font: 'Lora',
      weight: 400,
      fontSize: 96,
      color: config.colors?.ink || '#16161d',
      fontAtlas: ctx.fontAtlas,
      maxWidth: width * 0.9,
      align: 'center',
      anchor: 'center',
    });
    if (textMesh) {
      textMesh.position.set(0, 0, 0.01);
      group.add(textMesh);
    }
  } catch (e) {
    // text creation guarded to keep node robust
  }

  // ---- Cleanup ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    if (ctx.unregisterFrameCallback && billboardUpdate) {
      ctx.unregisterFrameCallback(billboardUpdate);
    }
    geometry.dispose();
    material.dispose();
    if (rawTexture && rawTexture.dispose) rawTexture.dispose();
    if (textMesh) {
      textMesh.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  return group;
}
